	L["If checked, the battlefield map will stay centered on your location as long as you are not in a dungeon.|n|nYou can hold shift while panning the map to temporarily prevent it from centering."] = "던전에 있지 않은 한 전장 지도가 항상 플레이어 위치 중심으로 유지됩니다.|n|n지도를 이동할 때 Shift 키를 누르고 있으면 일시적으로 중심 유지 기능을 해제할 수 있습니다."
	L["If checked, the default fullscreen map will be used.|n|nNote that enabling this option will lock out some of the other options."] = "기본 전체 화면 지도가 사용됩니다.|n|n이 옵션을 활성화하면 다른 일부 옵션이 사용 불가해집니다."
	L["If checked, the map will show a map of the dungeon or raid you are in, with bosses, entrances and level changes.|n|nUse the mouse wheel to zoom and drag to pan.|n|nRight-click the dungeon map to show the normal map until you next open the map."] = "현재 있는 던전이나 공격대의 지도가 우두머리, 입구, 층 이동 지점과 함께 표시됩니다.|n|n마우스 휠로 확대하고 드래그하여 이동합니다.|n|n던전 지도를 우클릭하면 다음에 지도를 열 때까지 일반 지도가 표시됩니다."
	L["If checked, the map will stay centered on your location as long as you are not in a dungeon.|n|nYou can hold shift while panning the map to temporarily prevent it from centering."] = "던전에 있지 않은 한 지도가 항상 현재 플레이어 위치 중심으로 유지됩니다.|n|n지도를 이동할 때 Shift 키를 누르고 있으면 일시적으로 중심 유지 기능을 해제할 수 있습니다."
	L["If checked, the minimap button will be shown."] = "미니맵 버튼이 표시됩니다."
	L["If checked, the minimum fishing skill levels will be shown."] = "최소 낚시 숙련도가 표시됩니다."
	L["If checked, town and city icons will not be shown on the continent maps."] = "대륙 지도에 마을 및 도시 아이콘이 표시되지 않습니다."
	L["If checked, unexplored areas of the map will be shown on the world map and the battlefield map."] = "지도에서 탐험되지 않은 지역이 세계 지도와 전장 지도에 표시됩니다."
	L["If checked, unexplored areas will be tinted."] = "탐험하지 않은 지역은 음영 처리됩니다."
	L["If checked, when your character changes zones, the map will automatically change to the new zone."] = "캐릭터가 지역을 변경할 때 지도가 자동으로 새 지역으로 전환됩니다."
	L["If checked, you can move the battlefield map by dragging any of its borders.|n|nYou can resize the battlefield map by dragging the bottom-right corner."] = "전장 지도의 가장자리를 드래그하여 이동할 수 있습니다.|n|n전장 지도의 크기는 오른쪽 하단 모서리를 드래그하여 조정할 수 있습니다."
	L["If checked, you can set a key to toggle the Leatrix Maps options panel."] = "Leatrix Maps 설정창을 열고 닫는 단축키를 지정할 수 있습니다."
	L["If checked, you will be able to customise the battlefield map."] = "전장 지도를 사용자 정의할 수 있습니다."
	L["If checked, you will be able to enlarge the player arrow."] = "플레이어 화살표를 확대할 수 있습니다."
	L["If checked, you will be able to scale and move the map.|n|nScale the map by dragging the scale handle in the bottom-right corner.|n|nMove the map by dragging the border and frame edges."] = "지도를 크기 조정하고 이동할 수 있습니다.|n|n오른쪽 하단 모서리의 크기 조정 핸들을 드래그하여 지도를 확대/축소합니다.|n|n테두리와 프레임 가장자리를 드래그하여 지도를 이동합니다."
	L["If checked, you will be able to set the opacity of the map."] = "지도의 투명도를 설정할 수 있습니다."
	L["If checked, you will be able to zoom further into the world map."] = "세계 지도를 더 확대할 수 있습니다."
	L["If checked, zone and continent dropdown menus will be shown in the map frame."] = "지도 프레임에 지역 및 대륙 드롭다운 메뉴가 표시됩니다."
	L["If checked, zone crossings will be shown.|n|nThese are arrows that indicate the zone exit pathways."] = "지역 경계가 표시됩니다.|n|n이 표시들은 지역 출구 경로를 나타내는 화살표입니다."
	L["If checked, zone levels will be shown on the continent maps."] = "대륙 지도에 지역 레벨이 표시됩니다."
